44:static inline float3 srgb_color4(E3DCOLOR ec)
45:{
46:  Color3 c = color3(ec);
47:  c.r = powf(c.r, 2.2f);
48:  c.g = powf(c.g, 2.2f);
49:  c.b = powf(c.b, 2.2f);
50:  return float3(c.r, c.g, c.b);
51:}
